/* 照片资源：lovart 生成，内联成 data URI。

   为什么内联而不是引外链：这个 pattern 最终要能塞进一个无依赖的单文件里，
   外链 CDN 会过期，过期之后这件东西就坏了一半。
   两张合计 17KB，比一次网络往返便宜。

   avatar  —— 暖红背景的人像特写，圆形裁切用
   tokyo   —— 浅草寺五重塔黄昏街景，历史条右侧的缩略图
*/

export const PHOTO_AVATAR =
  'data:image/jpeg;base64,';

export const PHOTO_TOKYO =
  'data:image/jpeg;base64,';

/* 展开卡顶部那张：夜晚城市天际线，跨江大桥灯带横贯中部 */
export const PHOTO_CITY =
  'data:image/jpeg;base64,';

/* 生成结果卡的照片：樱花枝框住富士山，一条公路收向远处。
   下三分之一本来就暗，白色标题压上去才不用再加一层黑纱。 */
export const PHOTO_FUJI =
  'data:image/jpeg;base64,';

/* 两个子任务各自的产物：近郊晨雾杉木林 / 夜晚霓虹街道。
   同一次生成、同一套调色 —— 它们是同一个 agent 派出去的两支，风格必须同源。 */
export const PHOTO_NATURE =
  'data:image/jpeg;base64,';

export const PHOTO_NIGHT =
  'data:image/jpeg;base64,';

/* 详情页那张要铺满全屏，瓦片那张 276px 撑到 390 会糊 —— 单独存一张大的。
   同一张原图的竖向裁切，塔和招牌留在上半部。 */
export const PHOTO_NIGHT_FULL =
  'data:image/jpeg;base64,';
